begin;
set local search_path=public,extensions;
select plan(30);
update auth.users set email_confirmed_at=now() where id in ('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000301');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
create temp table managed_service as select public.create_managed_service('10000000-0000-4000-8000-000000000001','Fictional Recovery Session','Fictional service management fixture.',50,10,9900) id;
grant select on managed_service to service_role;
select ok((select id is not null from managed_service),'active owner creates a service');
select is((select currency from services where id=(select id from managed_service)),'RON','currency is derived from organization');
select is((select status from services where id=(select id from managed_service)),'active','new service starts active');
select is(public.update_managed_service((select id from managed_service),'Fictional Recovery Session Updated','Updated fictional description.',55,15,10900),(select id from managed_service),'owner updates same-tenant service');
select is((select name from services where id=(select id from managed_service)),'Fictional Recovery Session Updated','updated service persists');
select throws_ok(format('select public.update_managed_service(%L,%L,%L,4,0,100)',(select id from managed_service),'Invalid',''),'23514',null,'duration below bound fails');
select throws_ok(format('select public.update_managed_service(%L,%L,%L,30,241,100)',(select id from managed_service),'Invalid',''),'23514',null,'buffer above bound fails');
select throws_ok(format('select public.update_managed_service(%L,%L,%L,30,0,-1)',(select id from managed_service),'Invalid',''),'23514',null,'negative price fails');
select is(public.set_managed_service_status((select id from managed_service),'archived'),'archived','owner archives service');
select is(public.set_managed_service_status((select id from managed_service),'archived'),'archived','archive retry is idempotent');
select is(public.set_managed_service_status((select id from managed_service),'active'),'active','owner reactivates service');
select throws_ok(format('select public.set_managed_service_status(%L,%L)',(select id from managed_service),'deleted'),'22023','invalid service status','invalid lifecycle transition fails');
select is(public.set_managed_service_staff((select id from managed_service),'13000000-0000-4000-8000-000000000102',true),true,'owner assigns eligible same-tenant staff');
select is(public.set_managed_service_staff((select id from managed_service),'13000000-0000-4000-8000-000000000102',true),true,'assignment retry is idempotent');
select is((select count(*) from service_staff where service_id=(select id from managed_service) and staff_profile_id='13000000-0000-4000-8000-000000000102'),1::bigint,'duplicate assignment remains impossible');
select is(public.set_managed_service_staff((select id from managed_service),'13000000-0000-4000-8000-000000000102',false),false,'owner unassigns staff');
select is(public.set_managed_service_staff((select id from managed_service),'13000000-0000-4000-8000-000000000102',false),false,'unassignment retry is idempotent');
select throws_ok(format('select public.set_managed_service_staff(%L,%L,true)',(select id from managed_service),'24000000-0000-4000-8000-000000000202'),'42501','eligible staff profile not found','cross-tenant staff identifier fails');
select throws_ok($$select public.update_managed_service('23000000-0000-4000-8000-000000000201','Forged','',30,0,100)$$,'42501','service not found','cross-tenant service identifier fails');
select throws_ok(format('update public.services set status=%L where id=%L','archived',(select id from managed_service)),'42501','service writes require the managed workflow','direct service lifecycle write is denied');
select throws_ok(format('delete from public.services where id=%L',(select id from managed_service)),'42501','service writes require the managed workflow','services cannot be hard-deleted directly');
select is((select count(*) from audit_logs where organization_id='10000000-0000-4000-8000-000000000001' and target_id=(select id from managed_service) and action in ('service.created','service.updated','service.archived','service.activated','service.staff_assigned','service.staff_unassigned')),6::bigint,'all effective operations write redacted audit events once');
select ok((select bool_and(changes='{}') from audit_logs where target_id=(select id from managed_service)),'audit payloads contain no form data');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","role":"authenticated"}',true);
select is((select count(*) from services where id=(select id from managed_service)),0::bigint,'owner B cannot read owner A managed service');
select throws_ok(format('select public.set_managed_service_status(%L,%L)',(select id from managed_service),'archived'),'42501','service not found','owner B cannot mutate owner A service');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000102","role":"authenticated"}',true);
select throws_ok($$select public.create_managed_service('10000000-0000-4000-8000-000000000001','Staff Forgery','',30,0,100)$$,'42501','organization not found','staff cannot create services');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000103","role":"authenticated"}',true);
select throws_ok($$select public.set_managed_service_status('12000000-0000-4000-8000-000000000101','archived')$$,'42501','service not found','client cannot mutate services');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000301","role":"authenticated"}',true);
select throws_ok($$select public.create_managed_service('30000000-0000-4000-8000-000000000001','Suspended Forgery','',30,0,100)$$,'42501','organization not found','suspended organization cannot mutate services');
reset role;set local role service_role;
update organization_memberships set status='inactive' where id='11000000-0000-4000-8000-000000000101';
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
select throws_ok($$select public.create_managed_service('10000000-0000-4000-8000-000000000001','Inactive Forgery','',30,0,100)$$,'42501','organization not found','inactive owner membership cannot mutate services');
reset role;set local role anon;
select throws_ok($$select public.set_managed_service_status('12000000-0000-4000-8000-000000000101','archived')$$,'42501',null,'anonymous cannot mutate services');
select * from finish();
rollback;
